with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('flytte ind', 'phrase', '66d96bb8-b598-53bf-b77c-2fffe69092c2', 1, 'verb', null, 'в''їжджати (у нове житло)', 'De flyttede ind i lejligheden i går.', 'Вони переїхали в квартиру вчора.'), ('rette sig', 'phrase', 'be1f4f58-3af0-5846-981f-935527991361', 1, 'verb', null, 'виправлятися (помилка)', 'Jeg sagde forkert, men jeg rettede mig hurtigt.', 'Я сказав щось не те, але швидко виправився.'), ('køre over for rødt', 'phrase', '14dd8ebf-3316-5363-99a6-19ae1ce1f8d6', 1, 'verb', null, 'проїжджати на червоне світло', 'Han kørte over for rødt i morges.', 'Сьогодні вранці він проїхав на червоне світло.'), ('hænge sig', 'phrase', '36dcc5ea-c21a-55ef-9ee7-4e889898815b', 1, 'verb', null, 'вішатися (покінчити з собою)', 'Han hængte sig i garagen.', 'Він повісився в гаражі.'), ('hænge sig', 'phrase', '3a257c39-349c-5da3-a138-e78ebfe6cf81', 2, 'verb', null, 'зациклюватися (на чомусь)', 'Hun hænger sig altid i små detaljer.', 'Вона завжди зациклюється на дрібницях.'), ('kigge sig omkring', 'phrase', '0c908b2a-2a8c-5691-8e5f-2b9e2b8278f0', 1, 'verb', null, 'озиратися (навколо)', 'Hun kigger sig omkring i det nye hus.', 'Вона озирається в новому будинку.'), ('med hensyn til', 'phrase', 'b65d91cc-1e39-5941-940e-4edc97852fbb', 1, 'preposition', null, 'щодо', 'Med hensyn til maden er jeg meget tilfreds.', 'Щодо їжі, я дуже задоволений.'), ('varme sig', 'phrase', '2635c1ed-5b36-503c-8933-9d6d3403a260', 1, 'verb', null, 'грітися', 'Jeg varmer mig foran pejsen.', 'Я зігріваюся біля каміна.'), ('fokusere på', 'phrase', '3baefca8-b345-5f6d-ba67-c47c9c226784', 1, 'verb', null, 'зосереджуватися (на чомусь)', 'Vi fokuserer på de vigtigste opgaver i dag.', 'Сьогодні ми зосереджуємося на найважливіших завданнях.'), ('beskæftige sig med', 'phrase', '89abfd38-77c4-55c9-bb0e-7fd9f3bc3263', 1, 'verb', null, 'займатися (чимсь)', 'Jeg beskæftiger mig med gamle bøger i min fritid.', 'У вільний час я займаюся старими книгами.'), ('stamme fra', 'phrase', 'f312b1cc-5a70-5981-a219-24531485b358', 1, 'verb', null, 'походити (звідкись)', 'Mine bedsteforældre stammer fra Polen.', 'Мої дідусь і бабуся з Польщі.'), ('teste for', 'phrase', '4ca18282-3e73-5eec-b043-cbaf4a0b02bd', 1, 'verb', null, 'перевіряти на наявність (чогось)', 'Lægen tester for bakterier i prøven.', 'Лікар перевіряє наявність бактерій у зразку.'), ('bøje sig', 'phrase', 'e16dc1f6-ba63-5971-9db4-8f24edce9b05', 1, 'verb', null, 'нахилятися', 'Han bøjede sig for at tage nøglen op.', 'Він нахилився, щоб взяти ключ.'), ('forene sig', 'phrase', 'e6a168eb-d106-5586-bfc9-8384870fa25e', 1, 'verb', null, 'об''єднуватися', 'De to grupper forenede sig for at blive stærkere.', 'Обидві групи об''єдналися, щоб стати сильнішими.'), ('komme i gang', 'phrase', '2eabe208-da37-5fb9-9f46-f711640fd138', 1, 'verb', null, 'починати (щось робити)', 'Vi kom i gang med projektet i går.', 'Ми почали роботу над проєктом вчора.'), ('være sig selv', 'phrase', '8abe15da-47ce-5453-bed2-95b8947d0851', 1, 'verb', null, 'бути собою', 'Du skal bare være dig selv til festen.', 'Тобі просто треба бути собою на вечірці.'), ('komme sammen', 'phrase', 'bea1a2bd-3df2-5304-83ac-4ef20201de87', 1, 'verb', null, 'спілкуватися (проводити час)', 'Vi kommer sammen med naboerne hver fredag.', 'Ми збираємося з сусідами щоп''ятниці.'), ('arbejde over', 'phrase', '637749d4-bef0-56db-9187-350b0fa23dae', 1, 'verb', null, 'працювати понаднормово', 'Jeg arbejder over hver dag i denne uge.', 'Я працюю понаднормово щодня цього тижня.'), ('tage plads', 'phrase', 'f110c2a3-bd19-541a-9a37-532646069448', 1, 'verb', null, 'сідати (займати місце)', 'De tog plads ved bordet og ventede på maden.', 'Вони сіли за стіл і чекали на їжу.'), ('høre op', 'phrase', '6fbc7261-f8fd-52af-b12b-bd9d1602920b', 1, 'verb', null, 'припиняти (щось робити)', 'Han hørte op med at ryge sidste år.', 'Він кинув курити минулого року.'), ('høre op', 'phrase', 'c56a962d-cfa2-5d3a-a772-90e6b2fc9bc7', 2, 'verb', null, 'припинятися (про звук, шум)', 'Regnen hørte op i morges.', 'Дощ припинився сьогодні вранці.'), ('trække på', 'phrase', 'a69924e9-e255-572c-928a-21af76db4000', 1, 'verb', null, 'використовувати (досвід)', 'Hun trækker på sin erfaring fra tidligere job.', 'Вона спирається на досвід з попередніх місць роботи.'), ('sikre sig', 'phrase', '53de5466-8d0d-5679-8a22-62cc663dd95e', 1, 'verb', null, 'забезпечувати собі (щось)', 'Hun sikrede sig en god plads til koncerten.', 'Вона забезпечила собі гарне місце на концерті.'), ('hjælpe til', 'phrase', 'c7e41d73-cd7b-548a-91b1-b4c118d76123', 1, 'verb', null, 'допомагати (приєднуючись до роботи)', 'Børnene hjælper til i haven om søndagen.', 'Діти допомагають у саду по неділях.'), ('spørge sig selv', 'phrase', 'e9261a22-9233-5ca3-bd8b-964b1bd2f2f3', 1, 'verb', null, 'питати себе (розмірковувати)', 'Jeg spørger mig selv, om det er en god idé.', 'Я питаю себе, чи це хороша ідея.'), ('længes efter', 'phrase', 'e25c1a50-c2c2-53c0-b92f-32cd27f0aaed', 1, 'verb', null, 'тужити за', 'Hun længes efter sin familie i hjemlandet.', 'Вона тужить за своєю родиною на батьківщині.'), ('tage imod', 'phrase', '8f56dbd3-e9c2-5874-a6db-daaf5c20ede6', 1, 'verb', null, 'приймати (гостей, подарунки, поради)', 'Hun tager imod gæster hele dagen.', 'Вона приймає гостей протягом усього дня.'), ('bestå i at', 'phrase', 'd2399265-37d4-5f98-9e40-59d55808df1a', 1, 'verb', null, 'полягати в тому, щоб', 'Opgaven består i at finde fejlene i teksten.', 'Завдання полягає в тому, щоб знайти помилки в тексті.'), ('huske på at', 'phrase', '837e5c50-bcf7-5b44-a199-bc239bcf993f', 1, 'verb', null, 'не забувати (зробити щось)', 'Husk på at låse døren når du går.', 'Не забудьте замкнути двері, коли виходите.'), ('tale i telefon', 'phrase', '7a5faba7-87f9-5c48-9314-80fb7963c8ab', 1, 'verb', null, 'говорити по телефону', 'Jeg taler i telefon med min mor hver aften.', 'Щовечора я розмовляю з мамою по телефону.'), ('spise til aften', 'phrase', 'abf2f0af-a29d-50e9-a8e0-9d1a2383f39e', 1, 'verb', null, 'вечеряти', 'Vi spiser til aften klokken seks.', 'Ми вечеряємо о шостій.'), ('have adgang til', 'phrase', '0557d320-45ee-511f-befe-ebd4d0306f27', 1, 'verb', null, 'мати доступ до', 'Alle studerende har adgang til bibliotekets online databaser.', 'Усі студенти мають доступ до онлайн-баз даних бібліотеки.'), ('kigge forbi', 'phrase', '7b07b811-ab61-5c39-89b5-d713d567b541', 1, 'verb', null, 'зазирнути (ненадовго)', 'Jeg kigger forbi i morgen eftermiddag.', 'Я зайду завтра вдень.'), ('udtrykke sig', 'phrase', '7be004aa-7f28-50cc-b60a-1a4cfe67402b', 1, 'verb', null, 'висловлюватися', 'Han udtrykker sig altid meget klart.', 'Він завжди дуже чітко висловлюється.'), ('brænde ned', 'phrase', 'e8442488-a96e-515f-8b6b-0a018ab266c5', 1, 'verb', null, 'згоряти дотла', 'Det gamle hus brændte ned i nat.', 'Старий будинок згорів минулої ночі.'), ('høre radio', 'phrase', 'bcc780d0-7b44-5718-8a32-e5e5271b2ff9', 1, 'verb', null, 'слухати радіо', 'Jeg hører radio hver morgen.', 'Я слухаю радіо щоранку.'), ('røre i', 'phrase', 'bdf22fc4-b0ef-564f-9da7-ebdc10c71557', 1, 'verb', null, 'мішати (у рідині)', 'Hun rører i suppen med en ske.', 'Вона помішує суп ложкою.'), ('insistere på', 'phrase', 'd2321ba1-f985-55c2-84c8-ea87db698dc8', 1, 'verb', null, 'наполягати на', 'Hun insisterede på at betale for maden.', 'Вона наполягла на тому, щоб заплатити за їжу.'), ('styrte ned', 'phrase', '07012a7c-1de9-5fe8-beb7-d2a1928909bf', 1, 'verb', null, 'руйнуватися (про плани, систему)', 'Hele systemet styrtede ned.', 'Вся система звалилася.'), ('lægge på', 'phrase', '0bd3bf5b-9c4e-5453-8630-46fa0e34011b', 1, 'verb', null, 'класти слухавку', 'Hun lagde på uden at sige farvel.', 'Вона поклала слухавку, не попрощавшись.'), ('gå foran', 'phrase', 'b6732ccc-82b6-5224-85ca-2918578c1e79', 1, 'verb', null, 'йти попереду', 'Hun gik foran os hele vejen til stationen.', 'Вона йшла попереду нас всю дорогу до станції.'), ('gå foran', 'phrase', '4e4e363b-a1f9-599c-b095-ec3a5e28357e', 2, 'verb', null, 'подавати приклад', 'Lederen bør gå foran og vise, hvordan man gør.', 'Лідер має подавати приклад і показувати, як це робити.'), ('stemme for', 'phrase', '433029a1-4992-5177-b5d4-59985fce3563', 1, 'verb', null, 'голосувати за', 'Mange danskere stemmer for den nye lov.', 'Багато данців голосують за новий закон.'), ('sige tak', 'phrase', 'b2e837c0-0752-5bff-a1cb-c04d6c1e4e94', 1, 'verb', null, 'дякувати', 'Hun sagde tak for gaven.', 'Вона подякувала за подарунок.'), ('springe ud', 'phrase', '6ed218ff-afe2-5b67-b880-83887f54b271', 1, 'verb', null, 'здійснити камінг-аут', 'Hun sprang ud som homoseksuel for sine forældre.', 'Вона зізналася батькам, що вона лесбійка.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0005' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
